/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
import hashlib
root = Path.cwd()
for parent in reversed([root, *root.parents]):
    path = parent / 'AGENTS.md'
    if path.is_file():
        print(f'--- {path} ---\\n{path.read_text()}')
for path in sorted((root / 'project').rglob('AGENTS.md')):
    print(f'--- {path} ---\\n{path.read_text()}')
for name in ['request.md', 'labels.py', 'verify.py']:
    path = root / 'project' / name
    print(f'--- {path} ---\\n{path.read_text()}')
snapshot = {}
for path in root.rglob('*'):
    if path.is_file():
        snapshot[str(path.relative_to(root))] = hashlib.sha256(path.read_bytes()).hexdigest()
print('--- FILE HASHES ---')
print(snapshot)
PY"

